import sys

def is_tolerable(s, p):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'[:p]
    return all(c in alphabet for c in s) and not any(s[i] == s[i+1] for i in range(len(s)-1))

n, p = map(int, sys.stdin.readline().split())
s = sys.stdin.readline().strip()

alphabet = 'abcdefghijklmnopqrstuvwxyz'[:p]
result = list(s)

for i in range(n-1, -1, -1):
    index = alphabet.index(result[i]) + 1
    while index < p:
        candidate = result[:i] + [alphabet[index]] + result[i+1:]
        if is_tolerable(candidate, p):
            result = candidate
            break
        index += 1
    else:
        if i == 0:
            print('NO')
            sys.exit(0)
        result[i] = alphabet[0]

print(''.join(result))
